-- Saját ERP-anyagelőzmények lapozásának lezárása. A jogosultságok változatlanok.
begin;
create or replace function public.erp_material_read(p_org uuid,p_actor uuid,p_session uuid,p_project uuid,p_role text,p_filter jsonb default '{}') returns jsonb language plpgsql stable security definer set search_path='' as $$
declare ctx jsonb;p erp.project_material_plans;rows jsonb;lots jsonb:='[]';events jsonb:='[]';groups jsonb:='[]';masters jsonb:='[]';vendors jsonb:='[]';notes jsonb;query text:=erp_private.material_findtext(coalesce(p_filter->>'query',''));selected uuid:=(p_filter->>'line_id')::uuid;selected_lot uuid:=(p_filter->>'lot_id')::uuid;person uuid;summary jsonb;result jsonb;begin
 ctx:=erp_private.material_context(p_org,p_actor,p_session,p_project,p_role);person:=(ctx->>'person_id')::uuid;
 if length(query)>200 or length(query)=1 then raise exception 'A keresés legalább két karakter legyen.' using errcode='22023';end if;
 if p_project is not null then select * into p from erp.project_material_plans where organization_id=p_org and project_id=p_project;end if;
 select coalesce(jsonb_agg(x.doc order by x.name,x.id),'[]') into rows from(select l.id,l.name,erp_private.material_line_view(l.id,p_role) doc from erp.project_material_lines l where l.plan_id=p.id and (selected is null or l.id=selected) and (p_role<>'client' or l.active and l.source_kind='quote') and (p_filter->>'show_archived'='true' or l.active or exists(select 1 from erp.material_lots z where z.line_id=l.id)) and (query='' or position(query in erp_private.material_findtext(l.name))>0) and (p_filter->'after_line'->>'id' is null or (l.name,l.id)>(p_filter->'after_line'->>'name',(p_filter->'after_line'->>'id')::uuid)) order by l.name,l.id limit 100)x;

 if p_role<>'client' then
 with balances as(select line_id,sum(depot) depot,sum(transit) transit,sum(site) site,sum(installed) installed from erp.material_lots group by line_id),grouped as(select coalesce(l.material_id,l.id) id,max(coalesce(m.name,l.name)) name,l.unit,sum(l.installed_plan) installed_plan,sum(l.purchase_plan) purchase_plan,sum(coalesce(b.depot,0)) depot,sum(coalesce(b.transit,0)) transit,sum(coalesce(b.site,0)) site,sum(coalesce(b.installed,0)) installed,bool_and(l.material_id is not null) mapped from erp.project_material_lines l left join erp.materials m on m.id=l.material_id left join balances b on b.line_id=l.id where l.plan_id=p.id and (l.active or b.line_id is not null) and (query='' or position(query in erp_private.material_findtext(coalesce(m.name,l.name)))>0) group by coalesce(l.material_id,l.id),l.unit)
 select coalesce(jsonb_agg(to_jsonb(x) order by x.name,x.id),'[]') into groups from(select g.id,g.name,g.unit,g.installed_plan::text,g.purchase_plan::text,g.depot::text,g.transit::text,g.site::text,g.installed::text,(g.depot+g.transit+g.site+g.installed)::text received,g.mapped from grouped g where p_filter->'after_group'->>'id' is null or (g.name,g.id)>(p_filter->'after_group'->>'name',(p_filter->'after_group'->>'id')::uuid) order by g.name,g.id limit 100)x;
 end if;
 if selected is not null and not exists(select 1 from erp.project_material_lines where id=selected and plan_id=p.id) or selected_lot is not null and not exists(select 1 from erp.material_lots a join erp.project_material_lines b on b.id=a.line_id where a.id=selected_lot and b.plan_id=p.id) then raise exception 'Idegen anyag vagy szállítmány.' using errcode='42501';end if;
 if p_role in('office','construction_lead') then
  select coalesce(jsonb_agg(to_jsonb(x) order by x.id),'[]') into lots from(select a.id,a.line_id,a.revision,a.vendor_id,a.place,a.expected_price::text,case when p_role='office' or a.price_actor=person then a.actual_price::text else null end actual_price,(p_role='office' or a.price_actor=person) as price_visible,a.ordered::text,a.depot::text,a.transit::text,a.site::text,a.installed::text,a.created_by,a.created_at,l.name,l.unit from erp.material_lots a join erp.project_material_lines l on l.id=a.line_id where l.plan_id=p.id and (selected is null or l.id=selected) and (selected_lot is null or a.id=selected_lot) and (p_filter->>'after_lot' is null or a.id>(p_filter->>'after_lot')::uuid) order by a.id limit 100)x;
  select coalesce(jsonb_agg(x.doc order by x.created_at desc,x.id desc),'[]') into events from(select e.id,e.created_at,jsonb_build_object('id',e.id,'lot_id',e.lot_id,'kind',e.kind,'quantity',e.quantity::text,'delta',e.delta,'actor_name',n.display_name,'role',e.active_role,'work_date',e.work_date,'created_at',e.created_at,'reason',e.reason,'reverses_id',e.reverses_id,'reversed_by',(select id from erp.material_movements r where r.reverses_id=e.id),'actual_price',case when p_role='office' or (e.after_state->>'price_actor')::uuid=person then e.after_state->'actual_price' else null end,'line_id',l.id,'name',l.name,'unit',l.unit) doc from erp.material_movements e join erp.material_lots a on a.id=e.lot_id join erp.project_material_lines l on l.id=a.line_id join erp.persons n on n.id=e.actor_id where l.plan_id=p.id and (selected is null or l.id=selected) and (selected_lot is null or e.lot_id=selected_lot) and (p_filter->'before_event'->>'id' is null or (e.created_at,e.id)<((p_filter->'before_event'->>'time')::timestamptz,(p_filter->'before_event'->>'id')::uuid)) order by e.created_at desc,e.id desc limit 100)x;
  select coalesce(jsonb_agg(to_jsonb(x) order by x.name,x.id),'[]') into masters from(select a.id,a.name,a.unit,a.vendor_id,(select name from erp.vendors where id=a.vendor_id) vendor_name,a.expected_price::text,a.pack::text,a.capacity::text,a.active,a.revision from erp.materials a where organization_id=p_org and (p_filter->>'master_id' is null or a.id=(p_filter->>'master_id')::uuid) and (a.active or p_role='office') and (query='' or position(query in erp_private.material_findtext(a.name))>0) and (p_filter->'after_master'->>'id' is null or (a.name,a.id)>(p_filter->'after_master'->>'name',(p_filter->'after_master'->>'id')::uuid)) order by a.name,a.id limit 100)x;
  select coalesce(jsonb_agg(to_jsonb(x) order by x.name,x.id),'[]') into vendors from(select a.* from erp.vendors a where organization_id=p_org and (p_filter->>'vendor_id' is null or a.id=(p_filter->>'vendor_id')::uuid) and (a.active or p_role='office') and (query='' or position(query in erp_private.material_findtext(a.name))>0) and (p_filter->'after_vendor'->>'id' is null or (a.name,a.id)>(p_filter->'after_vendor'->>'name',(p_filter->'after_vendor'->>'id')::uuid)) order by a.name,a.id limit 100)x;
 end if;
 select jsonb_build_object('line_count',count(*),'unmapped',count(*) filter(where material_id is null),'extra_count',count(*) filter(where source_kind='extra' and active)) into summary from erp.project_material_lines where plan_id=p.id and (p_role<>'client' or active and source_kind='quote');
 result:=jsonb_build_object('context',jsonb_build_object('person_id',person,'role',p_role,'project',ctx->'project','can_write',p_role in('office','construction_lead') and ctx->'project'->>'status'='running','can_plan',p_role='office' and ctx->'project'->>'status' in('waiting_start','running')),'plan',case when p.id is null then null else jsonb_build_object('id',p.id,'revision',p.revision,'quote_id',p.quote_id,'quote_version',p.quote_version) end,'summary',summary,'purchase_groups',groups,'lines',rows,'lots',lots,'events',events,'materials',masters,'vendors',vendors,'cursors',jsonb_build_object('group',case when jsonb_array_length(groups)=100 then jsonb_build_object('name',groups->-1->>'name','id',groups->-1->>'id') else null end,'line',case when jsonb_array_length(rows)=100 then jsonb_build_object('name',rows->-1->>'name','id',rows->-1->>'id') else null end,'lot',case when jsonb_array_length(lots)=100 then lots->-1->>'id' else null end,'event',case when jsonb_array_length(events)=100 then jsonb_build_object('time',events->-1->>'created_at','id',events->-1->>'id') else null end,'master',case when jsonb_array_length(masters)=100 then jsonb_build_object('name',masters->-1->>'name','id',masters->-1->>'id') else null end,'vendor',case when jsonb_array_length(vendors)=100 then jsonb_build_object('name',vendors->-1->>'name','id',vendors->-1->>'id') else null end));
 if p_role='office' then
  result:=result||jsonb_build_object('policy',erp_private.material_policy(p_org),'cost',case when p.id is null then null else erp_private.material_cost(p_org,p_project) end,'versions',coalesce((select jsonb_agg(x.doc order by x.version desc) from(select z.version,jsonb_build_object('version',z.version,'quote_version',z.quote_version,'created_at',z.created_at,'role',z.active_role) doc from erp.project_material_plan_versions z where z.plan_id=p.id and (p_filter->>'before_version' is null or z.version<(p_filter->>'before_version')::bigint) order by z.version desc limit 100)x),'[]'),'history',case when p_filter->>'plan_version' is null then null else (select document from erp.project_material_plan_versions where plan_id=p.id and version=(p_filter->>'plan_version')::bigint) end);
  result:=result||jsonb_build_object('catalog_events',coalesce((select jsonb_agg(x.doc order by x.created_at desc,x.id desc) from(select e.id,e.created_at,jsonb_build_object('id',e.id,'kind',e.kind,'created_at',e.created_at,'actor_name',n.display_name,'role',e.active_role,'document',e.document) doc from erp.material_catalog_events e join erp.persons n on n.id=e.actor_id where e.organization_id=p_org and (e.document->>'project_id')::uuid is not distinct from p_project and (p_filter->'before_catalog'->>'id' is null or (e.created_at,e.id)<((p_filter->'before_catalog'->>'time')::timestamptz,(p_filter->'before_catalog'->>'id')::uuid)) order by e.created_at desc,e.id desc limit 100)x),'[]'));
  if p_project is null then result:=result||jsonb_build_object('projects',coalesce((select jsonb_agg(jsonb_build_object('id',g.id,'name',g.name,'address',g.site_address,'status',g.work_status) order by g.name,g.id) from erp.garden_projects g where g.organization_id=p_org and g.work_type='construction' and g.accepted_quote_id is not null),'[]'));end if;
 end if;
 if p_role='office' then result:=result||jsonb_build_object('version_cursor',case when jsonb_array_length(result->'versions')=100 then result->'versions'->-1->'version' else null end,'catalog_cursor',case when jsonb_array_length(result->'catalog_events')=100 then jsonb_build_object('time',result->'catalog_events'->-1->>'created_at','id',result->'catalog_events'->-1->>'id') else null end);end if;
 return result;
end$$;
commit;
